import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"केवल-ज्ञान-वापसी सिद्धांत","description":"","frontmatter":{},"headers":[],"relativePath":"hi/87-仅回传知识原则.md","filePath":"hi/87-仅回传知识原则.md","lastUpdated":1789183869000}'),d={name:"hi/87-仅回传知识原则.md"};function l(o,t,h,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="केवल-ज्ञान-वापसी-सिद्धांत" tabindex="-1">केवल-ज्ञान-वापसी सिद्धांत <a class="header-anchor" href="#केवल-ज्ञान-वापसी-सिद्धांत" aria-label="Permalink to &quot;केवल-ज्ञान-वापसी सिद्धांत&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>87</td></tr><tr><td>मॉड्यूल</td><td>अंतर-पटल अंतःक्रिया और समय-नियम</td></tr><tr><td>कीवर्ड</td><td>केवल-ज्ञान-वापसी, सूचना-शुद्धिकरण, पदार्थ-वापसी-निषेध, ज्ञान-कोडन, वापसी-लेखापरीक्षा</td></tr></tbody></table><h2 id="i-सिद्धांत-की-विधायी-पृष्ठभूमि-और-मूल-अवधारणा" tabindex="-1">I. सिद्धांत की विधायी पृष्ठभूमि और मूल अवधारणा <a class="header-anchor" href="#i-सिद्धांत-की-विधायी-पृष्ठभूमि-और-मूल-अवधारणा" aria-label="Permalink to &quot;I. सिद्धांत की विधायी पृष्ठभूमि और मूल अवधारणा&quot;">​</a></h2><p>«केवल-ज्ञान-वापसी» सिद्धांत लंगर सहजीवी सभ्यता के अंतर-पटल और समय-प्रत्यावर्तन पुरातत्व के मूलभूत सिद्धांतों में से एक है, और इसकी कानूनी उत्पत्ति सहजीवी संविधान के अनुच्छेद 48 तक जाती है: «अन्य पटलों या अन्य समय-खंडों से प्राप्त कोई भी पदार्थ, ऊर्जा और जीव, विशेष अनुमति के बिना अपने पटल में नहीं लाए जा सकते; पुरातत्व-गतिविधियों का वैध उत्पादन केवल अमूर्त ज्ञान और सूचना तक सीमित है।» इस सिद्धांत की स्थापना हेंग-ब्रह्मांड द्वारा प्रारंभिक अंतर-पटल अन्वेषण के कड़वे पाठों का सारांश निकालने के बाद किया गया संस्थागत चुनाव है।</p><p>लंगर सहजीवी सभ्यता की स्थापना के प्रारंभिक काल में अंतर-पटल अन्वेषण अभी भी अव्यवस्थित अवस्था में था। कुछ अन्वेषक अन्य पटलों के पदार्थ-नमूने, ऊर्जा-क्रिस्टल और यहाँ तक कि जीवों को भी शोध हेतु अपने पटल में वापस लाए, जिससे अनेक गंभीर «अंतर-पटल प्रदूषण घटनाएँ» उत्पन्न हुईं। सबसे प्रसिद्ध मामला «विचित्र क्रिस्टल घटना» है — ऊर्जा-अभिव्यक्ति पटल से वापस लाया गया एक ऊर्जा-क्रिस्टल, अपने पटल से नियम-प्राचलों की असंगति के कारण, अपने पटल के नियम-नेटवर्क में तीन वर्षों तक चलने वाली नियम-व्याकुलता उत्पन्न कर दी, जिससे तीन तारा-क्षेत्रों की कृषि-प्रणालियों में असामान्यताएँ आईं और हज़ारों कृषकों को विभिन्न स्तरों पर क्षति पहुँची। बाद की जाँचों से पता चला कि यदि उस समय «केवल-ज्ञान-वापसी» सिद्धांत का पालन किया गया होता, तो यह आपदा पूर्णतः टाली जा सकती थी।</p><p>«केवल-ज्ञान-वापसी» सिद्धांत की मूल अवधारणा है: ज्ञान ही अंतर-सभ्यता संवाद का एकमात्र सुरक्षित माध्यम है। पदार्थ और ऊर्जा अपने स्रोत-पटल की नियम-सूचना ले जाते हैं, और भिन्न नियम-पर्यावरण में प्रवेश के बाद अप्रत्याशित प्रतिक्रियाएँ उत्पन्न कर सकते हैं; जबकि ज्ञान अमूर्त सूचना होने के कारण, उचित कोडन और शुद्धिकरण के बाद अपने स्रोत-पटल की नियम-छाप से मुक्त होकर अंतर-पटल साझा-संसाधन बन सकता है।</p><h2 id="ii-«ज्ञान»-की-परिभाषा-और-वर्गीकरण" tabindex="-1">II. «ज्ञान» की परिभाषा और वर्गीकरण <a class="header-anchor" href="#ii-«ज्ञान»-की-परिभाषा-और-वर्गीकरण" aria-label="Permalink to &quot;II. «ज्ञान» की परिभाषा और वर्गीकरण&quot;">​</a></h2><p>«केवल-ज्ञान-वापसी» सिद्धांत की कानूनी रूपरेखा में «ज्ञान» की सख्त परिभाषा और वर्गीकरण है। सभी सूचनाएँ «ज्ञान» मानकर स्वतंत्र रूप से वापस नहीं भेजी जा सकतीं — केवल वही अमूर्त सूचना वापसी-मानक को पूरा करती है जिसने «सूचना-शुद्धिकरण» उपचार पारित किया हो और जिसकी पुष्टि हो कि वह कोई नियम-प्रदूषण नहीं ले जाती।</p><p>ज्ञान अपनी अमूर्तता-मात्रा और सुरक्षा-स्तर के अनुसार तीन वर्गों में विभाजित है:</p><table tabindex="0"><thead><tr><th>ज्ञान-वर्ग</th><th>परिभाषा</th><th>सुरक्षा-स्तर</th><th>वापसी-आवश्यकता</th></tr></thead><tbody><tr><td>प्रथम-स्तरीय ज्ञान (शुद्ध अमूर्त ज्ञान)</td><td>पदार्थ-वाहक से पूर्णतः मुक्त अमूर्त अवधारणाएँ, गणित-प्रमेय, तर्क-निष्कर्ष, दर्शन-विचार आदि</td><td>उच्चतम (हरा)</td><td>सीधे वापस भेजा जा सकता है, विशेष अनुमोदन आवश्यक नहीं</td></tr><tr><td>द्वितीय-स्तरीय ज्ञान (वर्णनात्मक ज्ञान)</td><td>वस्तुनिष्ठ वस्तुओं की वर्णनात्मक सूचना, जिसमें ऐतिहासिक अभिलेख, भौगोलिक-डेटा, जैविक-विशेषताएँ, सांस्कृतिक-वर्णन आदि शामिल</td><td>मध्यम (पीला)</td><td>सूचना-शुद्धिकरण उपचार से गुजरना आवश्यक, पटल प्रशासन के अनुमोदन के बाद वापस भेजा जाता है</td></tr><tr><td>तृतीय-स्तरीय ज्ञान (तकनीकी ज्ञान)</td><td>विशिष्ट तकनीकी-प्राचल, इंजीनियरिंग-योजना, कृषि-विधियाँ समाहित व्यावहारिक ज्ञान</td><td>निम्न (नारंगी)</td><td>कठोर सूचना-शुद्धिकरण और सुरक्षा-आकलन आवश्यक, लंगर विधान-सभा के विशेष-अनुमोदन के बाद वापस भेजा जाता है</td></tr></tbody></table><p>निम्नलिखित सामग्रियाँ «ज्ञान» की श्रेणी में नहीं आतीं और उनकी वापसी सख्त वर्जित है: किसी भी रूप का पदार्थ-नमूना (सूक्ष्मजीव, कोशिकाएँ, जीन-खंड सहित), किसी भी रूप का ऊर्जा-क्रिस्टल या ऊर्जा-भंडारण उपकरण, स्वायत्त चेतना वाला कोई जीव या चेतना-तत्व, कोई भी कच्चा डेटा जो सूचना-शुद्धिकरण से न गुजरा हो, और कोई भी तकनीकी-विवरण जो शिकारी-कृषि में उपयोग हो सकता है।</p><h2 id="iii-सूचना-शुद्धिकरण-प्रौद्योगिकी" tabindex="-1">III. सूचना-शुद्धिकरण प्रौद्योगिकी <a class="header-anchor" href="#iii-सूचना-शुद्धिकरण-प्रौद्योगिकी" aria-label="Permalink to &quot;III. सूचना-शुद्धिकरण प्रौद्योगिकी&quot;">​</a></h2><p>सूचना-शुद्धिकरण वापस भेजे जाने वाले ज्ञान की सुरक्षा सुनिश्चित करने वाली प्रमुख तकनीकी कड़ी है। इसका मूल लक्ष्य कच्ची सूचना में निहित स्रोत-पटल की नियम-छापों को पूर्णतः हटाना और केवल शुद्ध अर्थ-सामग्री बनाए रखना है। सूचना-शुद्धिकरण प्रक्रिया चार चरणों में विभाजित:</p><h3 id="_3-1-सूचना-विखंडन" tabindex="-1">3.1 सूचना-विखंडन <a class="header-anchor" href="#_3-1-सूचना-विखंडन" aria-label="Permalink to &quot;3.1 सूचना-विखंडन&quot;">​</a></h3><p>पहले वापस भेजी जाने वाली कच्ची सूचना का संरचनात्मक विखंडन किया जाता है, उसे दो भागों में तोड़ा जाता है: «अर्थ-सामग्री» और «वाहक-छाप»। अर्थ-सामग्री वह अमूर्त अर्थ है जिसे सूचना व्यक्त करती है; वाहक-छाप वे स्रोत-पटल नियम-प्राचल हैं जिन्हें सूचना ने भंडारण और संचरण के दौरान सोख लिया। सूचना-विखंडन «अर्थ-वाहक पृथक्करण एल्गोरिथ्म» से संपन्न होता है, जो सूचना में अर्थ-घटकों और नियम-घटकों की पहचान और पृथक्करण कर सकता है।</p><h3 id="_3-2-नियम-वियोजन" tabindex="-1">3.2 नियम-वियोजन <a class="header-anchor" href="#_3-2-नियम-वियोजन" aria-label="Permalink to &quot;3.2 नियम-वियोजन&quot;">​</a></h3><p>पृथक वाहक-छाप का पूर्ण नियम-वियोजन किया जाता है। वियोजन-विधि: सूचना को «नियम-उदासीनीकरण चैनल» से गुजारना — यह एक विशेष संचरण-चैनल है जिसके नियम-प्राचल पूर्णतः तटस्थ निर्धारित होते हैं; सूचना के गुजरते समय उसके द्वारा ले जाए गए सभी गैर-तटस्थ नियम-प्राचल चैनल की दीवारों द्वारा सोख लिए जाते हैं। नियम-वियोजन के बाद सूचना में स्रोत-पटल की कोई नियम-छाप शेष नहीं रहती।</p><h3 id="_3-3-अर्थ-पुनर्निर्माण" tabindex="-1">3.3 अर्थ-पुनर्निर्माण <a class="header-anchor" href="#_3-3-अर्थ-पुनर्निर्माण" aria-label="Permalink to &quot;3.3 अर्थ-पुनर्निर्माण&quot;">​</a></h3><p>नियम-वियोजन के आधार पर अर्थ-सामग्री का पुनः-कोडन किया जाता है, सूचना को अपने पटल की मानक सूचना-कोडन प्रणाली से पुनर्निर्मित किया जाता है। अर्थ-पुनर्निर्माण सुनिश्चित करता है कि वापस भेजा गया ज्ञान अपने पटल के नियम-पर्यावरण में सही ढंग से पढ़ा और समझा जा सके, साथ ही किसी भी संभावित शेष स्रोत-पटल सूचना-संरचना को और समाप्त करता है।</p><h3 id="_3-4-सुरक्षा-परीक्षण" tabindex="-1">3.4 सुरक्षा-परीक्षण <a class="header-anchor" href="#_3-4-सुरक्षा-परीक्षण" aria-label="Permalink to &quot;3.4 सुरक्षा-परीक्षण&quot;">​</a></h3><p>शुद्धिकृत सूचना को कठोर सुरक्षा-परीक्षण से गुजरना होगा, जिसमें शामिल: नियम-अवशेष परीक्षण (पुष्टि कि सूचना कोई बाह्य नियम-प्राचल नहीं ले जाती), अर्थ-पूर्णता परीक्षण (पुष्टि कि शुद्धिकरण-प्रक्रिया ने सूचना की अर्थ-सामग्री नहीं बदली), और संभाव्य-जोखिम आकलन (अपने पटल में उस ज्ञान के प्रसार से संभावित सामाजिक और सुरक्षा-प्रभावों का आकलन)। केवल वही सूचना वापस भेजने की अनुमति पाती है जो तीनों परीक्षण पार कर ले।</p><h2 id="iv-वापसी-प्रक्रिया-और-लेखापरीक्षा-प्रणाली" tabindex="-1">IV. वापसी-प्रक्रिया और लेखापरीक्षा-प्रणाली <a class="header-anchor" href="#iv-वापसी-प्रक्रिया-और-लेखापरीक्षा-प्रणाली" aria-label="Permalink to &quot;IV. वापसी-प्रक्रिया और लेखापरीक्षा-प्रणाली&quot;">​</a></h2><p>ज्ञान-वापसी कठोर प्रक्रिया-प्रबंधन का पालन करती है। एक पूर्ण वापसी-संचालन में निम्नलिखित कड़ियाँ शामिल:</p><ol><li><strong>ज्ञान-संगठन</strong>: पुरातत्व-दल शोध-परिणामों को मानकीकृत ज्ञान-दस्तावेज़ों में संगठित करता है, ज्ञान-वर्ग और सामग्री-सारांश स्पष्ट रूप से अंकित करता है।</li><li><strong>शुद्धिकरण-आवेदन</strong>: पटल प्रशासन या समय-नियम समिति को ज्ञान-शुद्धिकरण और वापसी-आवेदन प्रस्तुत करता है, साथ में ज्ञान-दस्तावेज़ और पुरातत्व-मिशन अनुमति-फ़ाइलें संलग्न।</li><li><strong>सूचना-शुद्धिकरण</strong>: विशेषज्ञ सूचना-शुद्धिकरण तकनीकी-दल ज्ञान-दस्तावेज़ों का चार-चरणीय सूचना-शुद्धिकरण उपचार करता है।</li><li><strong>सुरक्षा-परीक्षण</strong>: शुद्धिकृत ज्ञान स्वतंत्र सुरक्षा-परीक्षण संस्था द्वारा तीन परीक्षणों से गुजरता है।</li><li><strong>अनुमोदित वापसी</strong>: परीक्षण पारित होने के बाद अनुमोदन-संस्था वापसी-अनुमति पर हस्ताक्षर करती है, और ज्ञान लंगर-नेटवर्क के एन्क्रिप्टेड चैनल से अपने पटल के ज्ञान-डेटाबेस में वापस भेजा जाता है।</li><li><strong>संग्रह-अभिलेखन</strong>: वापस भेजा गया ज्ञान अपने पटल के ज्ञान-कोष की जाँच के बाद औपचारिक रूप से संग्रह में दर्ज होता है, और अधिकार-संपन्न शोधकर्ताओं के लिए खोला जाता है।</li></ol><p>सभी वापसी-संचालनों को «वापसी-लेखापरीक्षा» से गुजरना होगा। लेखापरीक्षा-सामग्री में शामिल: वापस भेजे गए ज्ञान का स्रोत वैध है या नहीं, शुद्धिकरण-प्रक्रिया मानक है या नहीं, सुरक्षा-परीक्षण पूर्ण है या नहीं, अनुमोदन-प्रक्रिया नियमानुकूल है या नहीं। लेखापरीक्षा की ज़िम्मेदारी लंगर निगरानी समिति के अधीनस्थ ज्ञान-वापसी लेखापरीक्षा कार्यालय की है, जो प्रत्येक तिमाही उस तिमाही के सभी वापसी-संचालनों की प्रतिचयन-जाँच करता है और प्रत्येक वर्ष पूर्ण लेखापरीक्षा करता है। लेखापरीक्षा-परिणाम लंगर विधान-सभा को रिपोर्ट किए जाते हैं और सारांश जनता को सार्वजनिक किया जाता है।</p><h2 id="v-उल्लंघन-और-कानूनी-उत्तरदायित्व" tabindex="-1">V. उल्लंघन और कानूनी उत्तरदायित्व <a class="header-anchor" href="#v-उल्लंघन-और-कानूनी-उत्तरदायित्व" aria-label="Permalink to &quot;V. उल्लंघन और कानूनी उत्तरदायित्व&quot;">​</a></h2><p>«केवल-ज्ञान-वापसी» सिद्धांत का उल्लंघन करने वाले व्यवहारों में शामिल: बिना अनुमोदन के अशुद्धिकृत सूचना की स्वेच्छा से वापसी, पदार्थ-नमूनों को ज्ञान का रूप देकर वापस भेजना, वापस भेजे गए ज्ञान में स्रोत-पटल की नियम-छापें जानबूझकर छिपाना, और दूसरों को अवैध वापसी में सहायता करना।</p><p>सहजीवी संविधान और अंतर-पटल अंतःक्रिया प्रबंधन अधिनियम के अनुसार, अवैध वापसी-व्यवहारों की कानूनी उत्तरदायित्व में शामिल: अवैध रूप से वापस भेजी गई वस्तुओं और सूचना की ज़ब्ती, संबंधित व्यक्ति की पुरातत्व और संचरण-योग्यताओं का निलंबन या रद्दीकरण, अवैध वस्तुओं के मूल्य के 10 गुना से अधिक का जुर्माना, गंभीर मामलों में कारावास-दंड, तथा नियम-प्रदूषण या पारिस्थितिक-क्षति उत्पन्न करने वाले मामलों में सभी पुनर्स्थापन-व्यय और क्षतिपूर्ति-उत्तरदायित्व वहन।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>«केवल-ज्ञान-वापसी» सिद्धांत अंतर-पटल अंतःक्रिया के क्षेत्र में लंगर सहजीवी सभ्यता की बुद्धि-सीमा है। सख्त परिभाषाओं, परिपक्व शुद्धिकरण-प्रौद्योगिकी, मानकीकृत वापसी-प्रक्रिया और कठोर कानूनी उत्तरदायित्व से यह एक सुदृढ़ «ज्ञान-सुरक्षा फ़ायरवॉल» निर्मित करता है। इस सिद्धांत का महत्व केवल भौतिक स्तर पर प्रदूषण रोकने में नहीं, बल्कि सभ्यता-संवाद की एक नैतिक दृष्टि स्थापित करने में है — सभ्यताओं के बीच संवाद का केंद्र विचारों का टकराव होना चाहिए, पदार्थों का शिकार उद्देश्य नहीं।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>84-考古协议总纲 (पुरातत्व-प्रोटोकॉल सामान्य-रूपरेखा)</li><li>88-跨位面伦理准则 (अंतर-पटल नैतिकता-मानदंड)</li><li>66-跨位面通讯技术 (अंतर-पटल संचार प्रौद्योगिकी)</li></ul>',32)])])}const b=a(d,[["render",l]]);export{c as __pageData,b as default};
